using System.IO;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using Bird.App;
using Bird.Core;

internal static class Program
{
    private static int passed,failed;
    [STAThread] private static int Main()
    {
        var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};Theme.Install();Theme.Apply(false);
        var root=Directory.GetCurrentDirectory();var path=Path.Combine(root,"tests",".runs","ui-"+Guid.NewGuid(),"save.json");
        var state=new AppState(Path.Combine(root,"huashu-bird-sticker"),path,_=>{});
        void Test(string name,Action action){try{action();passed++;Console.WriteLine("PASS "+name);}catch(Exception e){failed++;Console.WriteLine("FAIL "+name+": "+e);}}
        void Check(bool value,string message){if(!value)throw new Exception(message);}
        var pet=new PetWindow(state);state.Pet=pet;
        Test("all initial WebP images decode with transparency",()=>{foreach(var id in ProgressEngine.InitialIds){var source=Images.Load(state.Catalog.ById[id]);Check(source!=null && source.Format==PixelFormats.Pbgra32,"decode "+id);}});
        Test("pet hover identifies both names",()=>{var image=Elements(pet.Content as DependencyObject).OfType<AlphaImage>().Single();var tooltip=(ToolTip)image.ToolTip;var texts=Elements(tooltip.Content as DependencyObject).OfType<TextBlock>().Select(t=>t.Text);Check(texts.Contains("珠颈斑鸠") && texts.Contains("Spilopelia chinensis"),"hover names missing");});
        var guide=new GuideWindow(state);
        Test("guide starts with four unlocked rows",()=>{var list=Elements(guide.Content as DependencyObject).OfType<ListBox>().Single();Check(list.Items.Count==4,"initial directory");Render(guide,"guide-light");});
        Test("all atlas never loads locked sticker and locked selection does not select pet",()=>{Click(guide,"全部图鉴");var list=Elements(guide.Content as DependencyObject).OfType<ListBox>().Single();Check(list.Items.Count==11011,"full atlas count");var locked=list.Items.Cast<BirdRow>().First(r=>!r.Unlocked);Check(locked.Thumbnail==null,"locked thumbnail leak");var before=state.Data.CurrentId;list.SelectedItem=locked;Check(state.Data.CurrentId==before,"locked pet selected");Render(guide,"guide-locked");});
        Test("select unlocked bird synchronizes current",()=>{Click(guide,"已解锁");var list=Elements(guide.Content as DependencyObject).OfType<ListBox>().Single();list.SelectedItem=list.Items.Cast<BirdRow>().First(r=>r.Bird.Id==ProgressEngine.InitialIds[1]);Check(state.Data.CurrentId==ProgressEngine.InitialIds[1],"current not synchronized");});
        Test("directory scientific sorting and taxonomy",()=>{var combo=Elements(guide.Content as DependencyObject).OfType<ComboBox>().Single();combo.SelectedIndex=2;var list=Elements(guide.Content as DependencyObject).OfType<ListBox>().Single();Check(list.Items.Cast<BirdRow>().Select(r=>r.Bird.Scientific).SequenceEqual(list.Items.Cast<BirdRow>().Select(r=>r.Bird.Scientific).Order(StringComparer.OrdinalIgnoreCase)),"scientific order");combo.SelectedIndex=3;var tree=Elements(guide.Content as DependencyObject).OfType<TreeView>().Single();Check(tree.Items.Count==1 && tree.Visibility==Visibility.Visible,"classification tree");combo.SelectedIndex=0;});
        var settings=new SettingsWindow(state);
        Test("settings change to dark and light",()=>{Click(settings,"深色 · 夜林");Check(state.Data.Dark,"dark not saved");Check(((SolidColorBrush)guide.Background).Color==((SolidColorBrush)app.Resources["Paper"]).Color,"guide window background did not follow dark theme");Check(((SolidColorBrush)settings.Background).Color==((SolidColorBrush)app.Resources["Paper"]).Color,"settings window background did not follow dark theme");Render(settings,"settings-dark");Render(guide,"guide-dark");Click(settings,"浅色 · 晨光");Check(!state.Data.Dark,"light not saved");Render(settings,"settings-light");});
        Test("pet size preference respects range",()=>{pet.SetSize(700);Check(state.Data.Size<=600 && state.Data.Size>=80,"size range");pet.SetSize(220);Check(Math.Abs(pet.Width-330)<0.1,"minimum toolbar width");Render(pet,"pet");});
        Test("pet detail entry always returns to current bird",()=>{state.OpenGuide();var opened=app.Windows.OfType<GuideWindow>().Single(w=>w.IsVisible);Click(opened,"全部图鉴");var list=Elements(opened.Content as DependencyObject).OfType<ListBox>().Single();list.SelectedItem=list.Items.Cast<BirdRow>().First(r=>!r.Unlocked);state.OpenGuide();Check(((BirdRow?)list.SelectedItem)?.Bird.Id==state.Data.CurrentId,"detail entry retained another bird");opened.Close();});
        Test("five settings activations expose developer actions",()=>{for(var i=0;i<4;i++)state.OpenSettings(true);Check(!state.Developer,"developer enabled early");state.OpenSettings(true);Check(state.Developer,"fifth activation did not enable developer");var developerSettings=app.Windows.OfType<SettingsWindow>().Single(w=>w.IsVisible);Check(Elements(developerSettings.Content as DependencyObject).OfType<Button>().Any(b=>b.Content?.ToString()=="重置为初始四种"),"developer controls missing");developerSettings.Hide();});
        Test("favorites grid columns selection removal and icon",()=>{
            foreach(var id in ProgressEngine.InitialIds.Take(3))state.ToggleFavorite(id);
            var favorites=new FavoritesWindow(state);var grid=Elements(favorites.Content as DependencyObject).OfType<ListBox>().Single();
            Check(grid.Items.Count==2,"default two-column rows");Check(guide.Icon!=null && favorites.Icon!=null,"bird icon missing");
            using(var iconStream=Application.GetResourceStream(new Uri("pack://application:,,,/BirdCompanion;component/Assets/bird.ico")).Stream){var iconType=Type.GetType("System.Drawing.Icon, System.Drawing.Common",true)!;using var nativeIcon=(IDisposable)Activator.CreateInstance(iconType,new object[]{iconStream})!;Check(nativeIcon!=null,"native tray icon decode");}
            var first=grid.Items.Cast<FavoriteCardRow>().First().Cards.First();first.Select.Execute(null);Check(state.Data.CurrentId==first.Bird.Id,"favorite selection");first.Remove.Execute(null);Check(!state.Data.FavoriteIds.Contains(first.Bird.Id),"favorite removal");
            state.Commit(()=>state.Data.FavoriteColumns=3);Check(grid.Items.Cast<FavoriteCardRow>().All(r=>r.Columns==3),"column setting not applied");
            state.ToggleFavorite(ProgressEngine.InitialIds[0]);state.ToggleFavorite(ProgressEngine.InitialIds[3]);
            state.Data.Unlocks.Add(new Unlock{Id="Phoenicurus_fuliginosus",Sequence=100});state.Engine.Restore(state.Data);state.ToggleFavorite("Phoenicurus_fuliginosus");
            state.Commit(()=>state.Data.FavoriteColumns=2);Theme.Apply(true);Render(favorites,"favorites-dark");Theme.Apply(false);Render(favorites,"favorites-light");favorites.Width=820;state.Commit(()=>state.Data.FavoriteColumns=4);Check(grid.Items.Cast<FavoriteCardRow>().All(r=>r.Cards.All(c=>c.Compact)),"dense layout missing");Render(favorites,"favorites-four-columns");favorites.Close();
        });
        Test("toolbar opacity switch label and favorite persistence",()=>{
            state.Commit(()=>state.Data.ToolbarOpacity=0.45);var bar=Elements(pet.Content as DependencyObject).OfType<Border>().Single(b=>Elements(b).OfType<Button>().Any(x=>x.Content?.ToString()=="随机"));Check(Math.Abs(bar.Opacity-0.45)<0.001,"toolbar opacity missing");
            state.Move(1);var banner=Elements(pet.Content as DependencyObject).OfType<Border>().Single(b=>!b.IsHitTestVisible);Check(banner.Visibility==Visibility.Visible,"switch name not shown");Check(Elements(banner).OfType<TextBlock>().Any(t=>t.Text==state.Current.Scientific),"switch scientific name missing");
            state.Commit(()=>{state.Data.RotationMinutes=2.5;state.Data.FavoritesOnly=true;});var saved=state.Store.Load();Check(saved.RotationMinutes==2.5 && saved.FavoritesOnly && saved.FavoriteIds.Count==state.Data.FavoriteIds.Count,"personalization not persisted");Render(pet,"pet-switch");
        });
        Test("settings roll back controls when storage fails",()=>{var config=new SettingsWindow(state);var combos=Elements(config.Content as DependencyObject).OfType<ComboBox>().ToArray();var range=combos[0];var columns=combos[1];var sliders=Elements(config.Content as DependencyObject).OfType<Slider>().ToArray();var opacity=sliders[1];var oldRange=range.SelectedIndex;var oldColumns=columns.SelectedItem;var oldOpacity=state.Data.ToolbarOpacity;using(var locked=new FileStream(state.Store.Path+".tmp",FileMode.OpenOrCreate,FileAccess.ReadWrite,FileShare.None)){range.SelectedIndex=oldRange==0?1:0;Check(range.SelectedIndex==oldRange,"range did not roll back");columns.SelectedItem=(int)oldColumns==1?2:1;Check(Equals(columns.SelectedItem,oldColumns),"columns did not roll back");opacity.Value=0.8;opacity.RaiseEvent(new System.Windows.Input.KeyEventArgs(System.Windows.Input.Keyboard.PrimaryDevice,new FakePresentationSource(),0,System.Windows.Input.Key.Right){RoutedEvent=System.Windows.Input.Keyboard.KeyUpEvent});Check(Math.Abs(opacity.Value-oldOpacity)<0.001,"opacity did not roll back");}state.Save();});
        Test("bird and switch label fade with two second lifetime and rapid latest selection",()=>{
            state.Data.FullscreenDnd=false;pet.Show();state.Move(1);var image=Elements(pet.Content as DependencyObject).OfType<AlphaImage>().Single();var banner=Elements(pet.Content as DependencyObject).OfType<Border>().Single(b=>!b.IsHitTestVisible);
            Check(image.HasAnimatedProperties,"bird switched without animation");Pump(0.1);Check(banner.Opacity>0 && banner.Opacity<1,"label did not fade in");state.Move(1);state.Move(1);var latest=state.Current;Pump(0.6);Check(ReferenceEquals(image.Source,Images.Load(latest)),"stale transition replaced latest bird");Check(Math.Abs(image.Opacity-1)<0.001,"bird did not finish fading");Pump(1.25);Check(banner.Opacity>0 && banner.Opacity<1,"label did not fade out");Pump(0.3);Check(banner.Visibility==Visibility.Collapsed && !image.HasAnimatedProperties,"name did not finish within two seconds or animation clock retained");state.Data.FullscreenDnd=true;
        });
        Test("fullscreen setting and physical monitor geometry",()=>{Check(!pet.ShowActivated,"automatic pet display steals foreground focus");var settingsDnd=new SettingsWindow(state);var check=Elements(settingsDnd.Content as DependencyObject).OfType<CheckBox>().Single(c=>c.Content?.ToString()?.StartsWith("全屏免打扰")==true);Check(check.IsChecked==true,"default DND checkbox");check.IsChecked=false;check.RaiseEvent(new RoutedEventArgs(System.Windows.Controls.Primitives.ButtonBase.ClickEvent));Check(!state.Data.FullscreenDnd && !state.Store.Load().FullscreenDnd,"DND off not persisted");check.IsChecked=true;check.RaiseEvent(new RoutedEventArgs(System.Windows.Controls.Primitives.ButtonBase.ClickEvent));Check(state.Data.FullscreenDnd,"DND on not persisted");Check(Native.CoversMonitor(-1920,0,0,1080,-1920,0,0,1080),"negative monitor bounds");Check(!Native.CoversMonitor(0,0,1920,1040,0,0,1920,1080),"work area mistaken for fullscreen");pet.ToggleUserVisibility();Check(!pet.IsVisible,"manual hide failed");state.Notify();Check(!pet.IsVisible,"settings refresh undid manual hide");pet.ShowByUser();});
        Test("chest speed editor unlock threshold and save",()=>{var window=new SettingsWindow(state);var speed=Elements(window.Content as DependencyObject).OfType<ChestSpeedSettings>().Single();var editor=Elements(speed).OfType<StackPanel>().Single(x=>x.Name=="ChestSpeedEditor");Check(editor.Visibility==Visibility.Collapsed,"early custom editor visible");state.Engine.UnlockAll();state.Data.Unlocks=state.Data.Unlocks.Take(50).ToList();state.Engine.Restore(state.Data);state.Notify();Check(editor.Visibility==Visibility.Collapsed,"50 custom editor visible");var id=state.Catalog.Birds.First(b=>!state.Data.Unlocks.Any(u=>u.Id==b.Id)).Id;state.Data.Unlocks.Add(new Unlock{Id=id,Sequence=1000});state.Engine.Restore(state.Data);state.Notify();Check(editor.Visibility==Visibility.Visible,"51 editor hidden");var input=Elements(speed).OfType<TextBox>().Single();input.Text="2";Elements(speed).OfType<Button>().Single().RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check(state.Engine.ChestIntervalSeconds==120 && state.Store.Load().ChestMinutes==2,"custom minutes not saved");});
        state.Stop();Console.WriteLine($"{passed}/{passed+failed} UI checks passed");app.Shutdown();return failed==0?0:1;
    }
    private static IEnumerable<DependencyObject> Elements(DependencyObject? root)
    {
        if(root==null)yield break;yield return root;
        foreach(var child in LogicalTreeHelper.GetChildren(root).OfType<DependencyObject>())foreach(var item in Elements(child))yield return item;
    }
    private static void Click(Window window,string text)=>Elements(window.Content as DependencyObject).OfType<Button>().First(b=>b.Content?.ToString()==text).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));
    private static void Pump(double seconds){var frame=new System.Windows.Threading.DispatcherFrame();var timer=new System.Windows.Threading.DispatcherTimer{Interval=TimeSpan.FromSeconds(seconds)};timer.Tick+=(_,_)=>{timer.Stop();frame.Continue=false;};timer.Start();System.Windows.Threading.Dispatcher.PushFrame(frame);}
    private static void Render(Window window,string name)
    {
        var content=(FrameworkElement)window.Content;content.Measure(new Size(window.Width,window.Height-40));content.Arrange(new Rect(0,0,window.Width,window.Height-40));content.UpdateLayout();
        var target=new RenderTargetBitmap((int)window.Width,(int)(window.Height-40),96,96,PixelFormats.Pbgra32);var background=new DrawingVisual();using(var dc=background.RenderOpen()){dc.DrawRectangle(window.Background,null,new Rect(0,0,window.Width,window.Height-40));}target.Render(background);target.Render(content);
        var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(target));Directory.CreateDirectory("docs/screenshots");using var file=File.Create("docs/screenshots/"+name+".png");encoder.Save(file);
    }
}
internal sealed class FakePresentationSource : PresentationSource {public override Visual? RootVisual {get;set;} public override bool IsDisposed=>false;protected override System.Windows.Media.CompositionTarget? GetCompositionTargetCore()=>null;}
